//! j8bytecode: j8's virtual instruction set, an accumulator-based register bytecode (compiled from JS by j8compiler,
//! run by j8executor, turned into machine code by j8jit). The dependency root: it depends on no other j8 crate.
//!
//! Every type (instructions, operators, constants, functions, modules) is defined in `insn.json` and generated by
//! `j8macros::enums!`.
//!
//! There is no text form. j8compiler builds each function's instructions as a [`Draft`] (`Vec<Insn>`), fuses and
//! assembles it into bytes ([`Function::code`]); from then on bytecode is bytes: the executor and the JIT decode
//! instructions at byte offsets ([`Function::insn_at`]), and a module's binary form (`Vec::<u8>::from(&module)` /
//! `Module::try_from(bytes)`, `Module::is_binary` tells it apart by the magic) carries the code as is.
extern crate alloc;

mod bin;
mod code;
mod fuse;
mod insn;

pub use bin::{BinError, Binary, Fixed, Reader};
pub use code::Insns;
pub use fuse::Unfused;
pub use insn::{BinaryOp, CompareOp, Const, Constant, Draft, EvalName, EvalScope, Function, FunctionKind, IcSlot, Insn, Label, Mode, Module, Opcode, PropertyKind, Reg, UnaryOp};
